// Normalize a Retell phone number into E.164 so Airtable matching is reliable.
// Handles: +15551234567 / (512) 555-1234 / 512-555-1234 / 15551234567
const body = $input.first().json.body || {};
const call = body.call || {};
const raw = call.from_number || call.to_number || '';
const digits = String(raw).replace(/\D/g, '');

let e164 = '';
if (digits.length === 10) e164 = '+1' + digits;
else if (digits.length === 11 && digits.startsWith('1')) e164 = '+' + digits;
else if (digits.length > 11) e164 = '+1' + digits.slice(-10);
else if (digits.length > 0) e164 = '+' + digits;

return [{ json: {
  normalizedPhone: e164,
  rawPhone: raw,
  callId: call.call_id || '',
  transcript: call.transcript || '',
  callStatus: call.call_status || ''
} }];

