// Pick the row whose Phone matches the normalized caller number.
// ALWAYS returns exactly one item so the downstream IF always runs.
// NOTE: Airtable's `fields` object does NOT contain the record id -- it lives
// on r.id. Merge it back in, otherwise the "does id exist" IF always fails.
const phone = ($('Normalize Phone').item.json.normalizedPhone || '').trim();
const digits = phone.replace(/\D/g, '');
const last10 = digits.slice(-10);
const rows = ($input.first().json.records) || [];
let hit = null;
for (const r of rows) {
  const f = r.fields || {};
  const cand = String(f['Phone'] ?? '').trim();
  const cd = cand.replace(/\D/g, '');
  if (!cd) continue;
  if (cand === phone || cd === digits || cd === last10 || ('+' + cd.slice(-10)) === phone) {
    hit = { json: { ...f, id: r.id, createdTime: r.createdTime } };
    break;
  }
}
return [hit ? hit : { json: {} }];

// Guard against duplicate call logging (Retell retries, double webhook hits).
// ALWAYS returns exactly one item. Merges r.id back in for the downstream IF.
const callId = ($('Normalize Phone').item.json.callId || '').trim();
const rows = ($input.first().json.records) || [];
let hit = null;
if (callId) {
  for (const r of rows) {
    const cid = String((r.fields || {})['Call ID'] ?? '').trim();
    if (cid === callId) { hit = { json: { ...r.fields, id: r.id } }; break; }
  }
}
return [hit ? hit : { json: {} }];

